mapper.select:
SELECT a.ID AS value,a.index_name AS label
FROM `system_docking`.api_platform_index_info a
LEFT JOIN `system_docking`.api_interface_system_platform_info b ON a.platform_id=b.ID
LEFT JOIN `system_docking`.api_interface_system_info c ON b.system_id=c.ID
WHERE a.is_enable='1' AND b.is_enable='1' AND c.is_enable='1' and a.is_keyPoint='1'

    AND a.is_monitor=#{params.is_monitor}


    AND a.platform_id=#{params.platform}


    AND a.index_type=#{params.indexType}


    AND c.system_code IN (${params.systemType})

SELECT a.ID AS value,a.platfrom_name AS label FROM `system_docking`.api_interface_system_platform_info a LEFT JOIN `system_docking`.api_interface_system_info b ON a.system_id=b.ID WHERE a.is_enable='1' AND b.is_enable='1'
AND b.system_code=#{params.systemType}
AND EXISTS (SELECT DISTINCT c.platform_id FROM `system_docking`.api_platform_index_info c WHERE c.index_type='1' AND c.is_enable='1' AND c.is_keyPoint='${params.is_keyPoint}' AND a.ID=c.platform_id)

SELECT table_name FROM information_schema.tables
WHERE table_schema=#{params.dataBase}

    AND table_name ${params.table_name}

SELECT b.resource_code AS value,a.resource_desc AS label,MAX(CAST(b.content AS SIGNED)) AS content FROM system_docking.api_system_resource a LEFT JOIN upm.api_interface_system_data20201002 b ON a.resource_code=b.resource_code WHERE a.is_enable='1'
AND b.index_id=#{params.index_id}
GROUP BY index_id ORDER BY content DESC LIMIT ${params.top}
